package org.clafer.frontend;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Set;

/**
 * Splits a model in the full Clafer language into tokens, as the compiler's
 * lexer does ({@code clafer.cf}, generated by BNFC and Alex).
 * <p>
 * The rules are the compiler's, and so is the longest match:
 * <ul>
 * <li>a name starts with a letter, and goes on with letters, digits,
 * {@code _} and {@code '}; a reserved word, e.g., {@code some} or {@code X},
 * is a {@link TokenKind#KEYWORD}. A letter is an ASCII letter or a Latin-1
 * letter, {@code À} to {@code ÿ} without {@code ×} and {@code ÷};</li>
 * <li>a number is an integer, a real with digits on both sides of the point,
 * or a double, a real with an exponent ({@code 1.5e-3});</li>
 * <li>a string has the escapes {@code \" \\ \n \t}, and may span lines;</li>
 * <li>comments ({@code //} to the end of the line, {@code /* *}{@code /})
 * and escapes ({@code [alloy| |]}, {@code [choco| |]}) are set aside, with
 * their spans.</li>
 * </ul>
 * The compiler's character classes are those of Latin-1, so a character after
 * {@code U+00FF} is an error anywhere, in a string or a comment too.
 * A column counts characters, and a tab moves to the next column after a
 * multiple of 8, as in the compiler's messages.
 * <p>
 * The lexer does not stop at an error, as the compiler's does: an unexpected
 * character is reported and skipped, and an unterminated string or comment is
 * reported and ends the input.
 */
public final class ClaferLexer {

    /**
     * The reserved words of {@code clafer.cf}.
     */
    static final Set<String> Keywords = Set.of(
            "F", "G", "U", "W", "X",
            "abstract", "after", "all", "always", "and", "assert", "before", "between", "disj", "each",
            "else", "enum", "eventually", "final", "finally", "finalref", "finaltarget", "follow",
            "globally", "historically", "if", "in", "initial", "initially", "let", "lonce", "lone",
            "max", "maximize", "min", "minimize", "must", "mux", "never", "next", "no", "not", "once",
            "one", "opt", "or", "precede", "previous", "product", "since", "some", "sometime", "sum",
            "then", "together", "triggered", "until", "weakuntil", "xor");

    /**
     * The symbols of {@code clafer.cf}, longest first so that the longest
     * match wins.
     */
    private static final String[] Symbols = {
        "-->>", "]->>",
        "<=>", "->>", "-->", "]->",
        "<<", ">>", "->", ":=", "..", "||", "&&", "=>", "<=", ">=", "!=", "<:", ":>", "++", "--", "**", "-[",
        "=", "[", "]", "{", "}", "`", ":", "?", "+", "*", "|", "!", "<", ">", "-", "/", "%", "#", ",",
        "&", ".", ";", "\\", "(", ")"
    };

    /**
     * The tokens of a model.
     *
     * @param tokens the tokens for the parser, ending with
     * {@link TokenKind#EOF}
     * @param others the comments and escapes, in order
     * @param diagnostics the errors, in order
     */
    public record Result(List<Token> tokens, List<Token> others, List<Diagnostic> diagnostics) {
    }

    private final String source;
    private int pos = 0;
    private int line = 1;
    private int column = 1;
    private final List<Token> tokens = new ArrayList<>();
    private final List<Token> others = new ArrayList<>();
    private final List<Diagnostic> diagnostics = new ArrayList<>();

    private ClaferLexer(String source) {
        this.source = source;
    }

    /**
     * Splits a model into tokens.
     *
     * @param source the text of the model
     * @return the tokens, the comments and escapes, and the errors
     */
    public static Result lex(String source) {
        ClaferLexer lexer = new ClaferLexer(source);
        lexer.run();
        return new Result(
                Collections.unmodifiableList(lexer.tokens),
                Collections.unmodifiableList(lexer.others),
                Collections.unmodifiableList(lexer.diagnostics));
    }

    private void run() {
        while (pos < source.length()) {
            char c = source.charAt(pos);
            if (c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\u000B') {
                advance();
            } else if (source.startsWith("//", pos)) {
                lineComment();
            } else if (source.startsWith("/*", pos)) {
                blockComment();
            } else if (source.startsWith("[alloy|", pos) || source.startsWith("[choco|", pos)) {
                escape();
            } else if (isLetter(c)) {
                word();
            } else if (isDigit(c)) {
                number();
            } else if (c == '"') {
                string();
            } else {
                symbol();
            }
        }
        tokens.add(new Token(TokenKind.EOF, "", SourceSpan.at(line, column)));
    }

    static boolean isLetter(char c) {
        return (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')
                || (c >= '\u00C0' && c <= '\u00FF' && c != '\u00D7' && c != '\u00F7');
    }

    /**
     * Moves past a character of a string, comment or escape, which must be
     * a Latin-1 character; reports the first that is not in each token.
     */
    private boolean advanceLatin1(boolean reported) {
        if (!reported && peek(0) > '\u00FF') {
            diagnostics.add(new Diagnostic(SourceSpan.at(line, column),
                    "Unexpected character " + describe(peek(0)) + ": only Latin-1 characters are allowed"));
            reported = true;
        }
        advance();
        return reported;
    }

    private static boolean isDigit(char c) {
        return c >= '0' && c <= '9';
    }

    private char peek(int offset) {
        int i = pos + offset;
        return i < source.length() ? source.charAt(i) : '\0';
    }

    /**
     * Moves past one character, as Alex does: a tab to the column after the
     * next multiple of 8, a line feed to the next line, anything else, a
     * carriage return included, one column.
     */
    private void advance() {
        char c = source.charAt(pos++);
        if (c == '\n') {
            line++;
            column = 1;
        } else if (c == '\t') {
            column = ((column + 7) / 8) * 8 + 1;
        } else {
            column++;
        }
    }

    private void advance(int n) {
        for (int i = 0; i < n; i++) {
            advance();
        }
    }

    private Token emit(List<Token> into, TokenKind kind, int startPos, int startLine, int startColumn) {
        Token token = new Token(kind, source.substring(startPos, pos), new SourceSpan(startLine, startColumn, line, column));
        into.add(token);
        return token;
    }

    private void lineComment() {
        int startPos = pos, startLine = line, startColumn = column;
        boolean reported = false;
        while (pos < source.length() && source.charAt(pos) != '\n') {
            reported = advanceLatin1(reported);
        }
        emit(others, TokenKind.COMMENT, startPos, startLine, startColumn);
    }

    private void blockComment() {
        int startPos = pos, startLine = line, startColumn = column;
        advance(2);
        boolean reported = false;
        while (pos < source.length() && !source.startsWith("*/", pos)) {
            reported = advanceLatin1(reported);
        }
        if (pos < source.length()) {
            advance(2);
            emit(others, TokenKind.COMMENT, startPos, startLine, startColumn);
        } else {
            unterminated("comment", startPos, startLine, startColumn);
        }
    }

    /**
     * {@code [alloy| ... |]}: up to the first {@code |]}.
     */
    private void escape() {
        int startPos = pos, startLine = line, startColumn = column;
        advance(7);
        boolean reported = false;
        while (pos < source.length() && !source.startsWith("|]", pos)) {
            reported = advanceLatin1(reported);
        }
        if (pos < source.length()) {
            advance(2);
            emit(others, TokenKind.ESCAPE, startPos, startLine, startColumn);
        } else {
            unterminated("escape", startPos, startLine, startColumn);
        }
    }

    private void unterminated(String what, int startPos, int startLine, int startColumn) {
        diagnostics.add(new Diagnostic(new SourceSpan(startLine, startColumn, line, column), "Unterminated " + what));
    }

    private void word() {
        int startPos = pos, startLine = line, startColumn = column;
        while (pos < source.length() && (isLetter(peek(0)) || isDigit(peek(0)) || peek(0) == '_' || peek(0) == '\'')) {
            advance();
        }
        String text = source.substring(startPos, pos);
        emit(tokens, Keywords.contains(text) ? TokenKind.KEYWORD : TokenKind.WORD, startPos, startLine, startColumn);
    }

    /**
     * An integer, a real if a point and a digit follow the digits, so that
     * {@code 1..2} is a range of integers, and a double if an exponent follows
     * the real.
     */
    private void number() {
        int startPos = pos, startLine = line, startColumn = column;
        digits();
        TokenKind kind = TokenKind.INT;
        if (peek(0) == '.' && isDigit(peek(1))) {
            kind = TokenKind.DECIMAL;
            advance();
            digits();
            int sign = peek(1) == '-' ? 1 : 0;
            if (peek(0) == 'e' && isDigit(peek(1 + sign))) {
                kind = TokenKind.DOUBLE;
                advance(1 + sign);
                digits();
            }
        }
        emit(tokens, kind, startPos, startLine, startColumn);
    }

    private void digits() {
        while (pos < source.length() && isDigit(peek(0))) {
            advance();
        }
    }

    /**
     * A string, which may span lines. An unknown escape is reported, and the
     * string goes on after it.
     */
    private void string() {
        int startPos = pos, startLine = line, startColumn = column;
        advance();
        boolean reported = false;
        while (pos < source.length()) {
            char c = peek(0);
            if (c == '"') {
                advance();
                emit(tokens, TokenKind.STRING, startPos, startLine, startColumn);
                return;
            }
            if (c == '\\') {
                int escapeLine = line, escapeColumn = column;
                advance();
                if (pos < source.length() && "\"\\nt".indexOf(peek(0)) < 0) {
                    diagnostics.add(new Diagnostic(SourceSpan.at(escapeLine, escapeColumn),
                            "Unknown escape in a string; use \\\", \\\\, \\n or \\t"));
                }
                if (pos < source.length()) {
                    advance();
                }
            } else {
                reported = advanceLatin1(reported);
            }
        }
        unterminated("string", startPos, startLine, startColumn);
    }

    private void symbol() {
        int startPos = pos, startLine = line, startColumn = column;
        for (String symbol : Symbols) {
            if (source.startsWith(symbol, pos)) {
                advance(symbol.length());
                emit(tokens, TokenKind.SYMBOL, startPos, startLine, startColumn);
                return;
            }
        }
        char c = peek(0);
        advance();
        diagnostics.add(new Diagnostic(SourceSpan.at(startLine, startColumn), "Unexpected character " + describe(c)));
    }

    private static String describe(char c) {
        return c >= ' ' && c <= '~' ? "'" + c + "'" : String.format("U+%04X", (int) c);
    }
}
